solution:
LIMIT, WINDOW = [int(x) for x in input().split()]
hits = {}


def allow(key, now):
    recent = [t for t in hits.get(key, []) if now - t < WINDOW]
    if len(recent) >= LIMIT:
        hits[key] = recent
        return False
    recent.append(now)
    hits[key] = recent
    return True


for _ in range(int(input())):
    key, now = input().split()
    print("ALLOW" if allow(key, int(now)) else "DENY")

